use usage_argv::{Arg, Command, Flag, Parser};
use std::ffi::OsStr;
static U: Flag = Flag { name: "update", shorts: b"u", ..Flag::EMPTY };
static A: Flag = Flag { name: "ask", shorts: b"a", ..Flag::EMPTY };
static PACKAGE: Arg = Arg { name: "package", ..Arg::EMPTY };
static INSTALL: Command = Command { name: "install", flags: &[&U, &A], args: &[&PACKAGE], ..Command::EMPTY };
static ROOT: Command = Command { name: "em", subcommands: &[&INSTALL], default_subcommand: Some(&INSTALL), ..Command::EMPTY };
fn main() {
 for words in [vec!["firefox"], vec!["-ua", "@world"], vec!["install", "-ua", "@world"]] {
  println!("{words:?}");
  let args: Vec<&OsStr> = words.iter().map(OsStr::new).collect();
  let mut p = Parser::new(&ROOT, &args);
  while let Some(event) = p.next_event() { match event { Ok(e) => println!("{e:?}"), Err(e) => {println!("{e:?}"); break;} } }
 }
}
