use std::ffi::OsStr;
use usage_derive::{Args, Cli, Subcommands};

#[derive(Cli)]
#[usage(bin = "em", default_subcommand = "install", default_subcommand_flags, unknown_flags = "error")]
struct Em {
    #[usage(short = 'p')]
    pretend: bool,
    #[usage(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommands)]
enum Commands {
    Install(Install),
    Query,
}

#[derive(Args)]
struct Install {
    #[usage(short = 'u')]
    update: bool,
    #[usage(short = 'a')]
    ask: bool,
    package: Option<String>,
}

#[test]
fn default_flags_bind_to_the_derived_child_and_parent_prefix_keeps_its_owner() {
    let parsed = Em::parse_from(&["-p", "-ua", "@world"].map(OsStr::new)).unwrap();
    assert!(parsed.pretend);
    let Some(Commands::Install(install)) = parsed.command else { panic!("expected install") };
